-- ============================================================================
-- prova_objetos.sql - READ-ONLY catalog evidence, one row per check.
-- Generated by gen_prova.py from backend/migrations/*.sql at origin/main ae2aac2
-- (79 top-level files; private_runtime/ excluded).
--
-- Output columns: migration, check_id, kind, ok, detail
--   ok = true  -> the migration's effect is present in this database
--   ok = false -> the effect is absent (or differs)
--   ok = NULL  -> not object-provable here (data_only / data_part_not_checked /
--                 conditional no-op / role-or-object missing for a
--                 has_*_privilege check). Read the detail column.
--   No migration is fully superseded; checks marked "partial" in the detail
--   prove the effect is present but a later file re-issues the same effect.
--
-- Safety: one READ ONLY transaction, ROLLBACK at the end; only pg_catalog views,
-- to_reg*(), has_*_privilege() on OIDs, pg_get_*def()/pg_get_expr(); no DO, no
-- SET, no temp objects, never reads application tables, never prints row data
-- or object comment text. Missing objects yield false/NULL, never an error.
--
-- Run (example):  psql "$DATABASE_URL" -X --csv -f prova_objetos.sql > prova.csv
-- ============================================================================

\set ON_ERROR_STOP on
BEGIN TRANSACTION READ ONLY;

SELECT checks.migration, checks.check_id, checks.kind, checks.ok, checks.detail
FROM (
  SELECT '0001_extensions_and_enums.sql'::text AS migration, 'c01_ext_pgcrypto'::text AS check_id, 'extension'::text AS kind, x.ok, ('extension pgcrypto installed (weak: Supabase preinstalls it) | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
    FROM (SELECT EXISTS (SELECT 1 FROM pg_extension AS x WHERE x.extname = 'pgcrypto') AS ok, coalesce((SELECT 'installed in schema ' || n.nspname FROM pg_extension AS x JOIN pg_namespace AS n ON n.oid = x.extnamespace WHERE x.extname = 'pgcrypto'), 'absent') AS obs) AS x
  UNION ALL
  SELECT '0001_extensions_and_enums.sql'::text AS migration, 'c02_enum_types'::text AS check_id, 'enum'::text AS kind, x.ok, ('all 25 enum types of 0001 exist in public | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
    FROM (SELECT count(*) FILTER (WHERE ty.oid IS NOT NULL) = 25 AS ok, format('%s/%s enum types present; missing: %s', count(*) FILTER (WHERE ty.oid IS NOT NULL), 25, coalesce(string_agg(replace(t.name, 'public.', ''), ',') FILTER (WHERE ty.oid IS NULL), 'none')) AS obs FROM unnest(ARRAY['public.igreja_status', 'public.pessoa_genero', 'public.pessoa_tipo', 'public.pessoa_etapa', 'public.pessoa_subetapa', 'public.pessoa_acompanhamento', 'public.app_user_status', 'public.user_role_papel', 'public.role_perm_papel', 'public.conversation_estado', 'public.message_direcao', 'public.message_autor', 'public.work_queue_tipo', 'public.work_queue_status', 'public.report_status', 'public.report_origem', 'public.broadcast_modo', 'public.broadcast_repeticao', 'public.broadcast_status', 'public.whatsapp_status', 'public.subscription_status', 'public.system_manager_papel', 'public.consolidacao_tipo', 'public.decision_vinculo', 'public.multiplicacao_status']::text[]) AS t(name) LEFT JOIN pg_type AS ty ON ty.oid = to_regtype(t.name)::oid AND ty.typtype = 'e') AS x
  UNION ALL
  SELECT '0001_extensions_and_enums.sql'::text AS migration, 'c03_enum_igreja_status'::text AS check_id, 'enum'::text AS kind, x.ok, ('igreja_status has ativa/suspensa/aguardando_aprovacao/inadimplente | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
    FROM (SELECT coalesce((SELECT count(DISTINCT e.enumlabel) FROM pg_enum AS e WHERE e.enumtypid = to_regtype('public.igreja_status')::oid AND e.enumlabel = ANY (ARRAY['ativa', 'suspensa', 'aguardando_aprovacao', 'inadimplente']::text[])) = 4, false) AS ok, CASE WHEN to_regtype('public.igreja_status') IS NULL THEN 'type absent' ELSE 'labels: ' || coalesce((SELECT string_agg(e.enumlabel, ',' ORDER BY e.enumsortorder) FROM pg_enum AS e WHERE e.enumtypid = to_regtype('public.igreja_status')::oid), '') END AS obs) AS x
  UNION ALL
  SELECT '0002_schema_tables.sql'::text AS migration, 'c01_tables'::text AS check_id, 'table'::text AS kind, x.ok, ('all 26 tables of 0002 exist | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
    FROM (SELECT count(*) FILTER (WHERE c.oid IS NOT NULL) = 26 AS ok, format('%s/%s tables ok; failing: %s', count(*) FILTER (WHERE c.oid IS NOT NULL), 26, coalesce(string_agg(replace(t.name, 'public.', ''), ',') FILTER (WHERE NOT coalesce(c.oid IS NOT NULL, false)), 'none')) AS obs FROM unnest(ARRAY['public.igrejas', 'public.pessoas', 'public.app_users', 'public.user_roles', 'public.role_permissions', 'public.celulas', 'public.cell_alerts', 'public.conversations', 'public.messages', 'public.work_queue_items', 'public.reports', 'public.broadcasts', 'public.events', 'public.whatsapp_connections', 'public.agent_configs', 'public.llm_credentials', 'public.crons', 'public.subscriptions', 'public.system_managers', 'public.consolidacoes', 'public.consolidacao_etapas', 'public.decisions', 'public.multiplicacoes', 'public.consent_records', 'public.ai_usage_logs', 'public.agent_conversation_logs']::text[]) AS t(name) LEFT JOIN pg_class AS c ON c.oid = to_regclass(t.name)::oid AND c.relkind IN ('r', 'p')) AS x
  UNION ALL
  SELECT '0002_schema_tables.sql'::text AS migration, 'c02_cols'::text AS check_id, 'column'::text AS kind, x.ok, ('pessoas core columns with types/nullability | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
    FROM (SELECT count(*) FILTER (WHERE a.attnum IS NOT NULL AND (e.typ = '' OR CASE WHEN e.typ LIKE 'u:%' THEN a.atttypid = to_regtype(substr(e.typ, 3))::oid ELSE format_type(a.atttypid, a.atttypmod) = e.typ END) AND (e.nn IS NULL OR a.attnotnull = e.nn)) = 4 AS ok, format('%s/%s columns ok; failing: %s', count(*) FILTER (WHERE a.attnum IS NOT NULL AND (e.typ = '' OR CASE WHEN e.typ LIKE 'u:%' THEN a.atttypid = to_regtype(substr(e.typ, 3))::oid ELSE format_type(a.atttypid, a.atttypmod) = e.typ END) AND (e.nn IS NULL OR a.attnotnull = e.nn)), 4, coalesce(string_agg(e.col || '=' || coalesce(format_type(a.atttypid, a.atttypmod) || CASE WHEN a.attnotnull THEN ' not null' ELSE ' null' END, 'absent'), '; ') FILTER (WHERE NOT coalesce(a.attnum IS NOT NULL AND (e.typ = '' OR CASE WHEN e.typ LIKE 'u:%' THEN a.atttypid = to_regtype(substr(e.typ, 3))::oid ELSE format_type(a.atttypid, a.atttypmod) = e.typ END) AND (e.nn IS NULL OR a.attnotnull = e.nn), false)), 'none')) AS obs FROM (VALUES ('telefone', 'text', true), ('presencas_celula', 'integer', true), ('apto_proxima_cd', 'boolean', true), ('tipo', 'u:public.pessoa_tipo', NULL::boolean)) AS e(col, typ, nn) LEFT JOIN pg_attribute AS a ON a.attrelid = to_regclass('public.pessoas')::oid AND a.attname = e.col AND a.attnum > 0 AND NOT a.attisdropped) AS x
  UNION ALL
  SELECT '0002_schema_tables.sql'::text AS migration, 'c03_cols2'::text AS check_id, 'column'::text AS kind, x.ok, ('celulas.cobertura_espiritual text not null, dia_reuniao text | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
    FROM (SELECT count(*) FILTER (WHERE a.attnum IS NOT NULL AND (e.typ = '' OR CASE WHEN e.typ LIKE 'u:%' THEN a.atttypid = to_regtype(substr(e.typ, 3))::oid ELSE format_type(a.atttypid, a.atttypmod) = e.typ END) AND (e.nn IS NULL OR a.attnotnull = e.nn)) = 2 AS ok, format('%s/%s columns ok; failing: %s', count(*) FILTER (WHERE a.attnum IS NOT NULL AND (e.typ = '' OR CASE WHEN e.typ LIKE 'u:%' THEN a.atttypid = to_regtype(substr(e.typ, 3))::oid ELSE format_type(a.atttypid, a.atttypmod) = e.typ END) AND (e.nn IS NULL OR a.attnotnull = e.nn)), 2, coalesce(string_agg(e.col || '=' || coalesce(format_type(a.atttypid, a.atttypmod) || CASE WHEN a.attnotnull THEN ' not null' ELSE ' null' END, 'absent'), '; ') FILTER (WHERE NOT coalesce(a.attnum IS NOT NULL AND (e.typ = '' OR CASE WHEN e.typ LIKE 'u:%' THEN a.atttypid = to_regtype(substr(e.typ, 3))::oid ELSE format_type(a.atttypid, a.atttypmod) = e.typ END) AND (e.nn IS NULL OR a.attnotnull = e.nn), false)), 'none')) AS obs FROM (VALUES ('cobertura_espiritual', 'text', true), ('dia_reuniao', 'text', false)) AS e(col, typ, nn) LEFT JOIN pg_attribute AS a ON a.attrelid = to_regclass('public.celulas')::oid AND a.attname = e.col AND a.attnum > 0 AND NOT a.attisdropped) AS x
  UNION ALL
  SELECT '0002_schema_tables.sql'::text AS migration, 'c04_fk_pessoas_celula'::text AS check_id, 'fk'::text AS kind, x.ok, ('FK pessoas(celula_id) -> celulas (circular FK added last) | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
    FROM (SELECT count(*) > 0 AS ok, CASE WHEN count(*) = 0 THEN 'no matching foreign key' ELSE format('%s matching FK: %s', count(*), string_agg(con.conname, ',')) END AS obs FROM pg_constraint AS con WHERE con.conrelid = to_regclass('public.pessoas')::oid AND con.contype = 'f' AND con.confrelid = to_regclass('public.celulas')::oid AND con.conkey = (SELECT array_agg(a.attnum ORDER BY x.ord) FROM unnest(ARRAY['celula_id']::text[]) WITH ORDINALITY AS x(col, ord) JOIN pg_attribute AS a ON a.attrelid = con.conrelid AND a.attname = x.col)) AS x
  UNION ALL
  SELECT '0002_schema_tables.sql'::text AS migration, 'c05_indexes'::text AS check_id, 'index'::text AS kind, x.ok, ('all 26 idx_* indexes of 0002 exist on their tables | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
    FROM (SELECT count(*) FILTER (WHERE i.indexrelid IS NOT NULL AND i.indrelid = to_regclass(e.tbl)::oid) = 26 AS ok, format('%s/%s indexes ok; failing: %s', count(*) FILTER (WHERE i.indexrelid IS NOT NULL AND i.indrelid = to_regclass(e.tbl)::oid), 26, coalesce(string_agg(replace(e.idx, 'public.', ''), ',') FILTER (WHERE NOT coalesce(i.indexrelid IS NOT NULL AND i.indrelid = to_regclass(e.tbl)::oid, false)), 'none')) AS obs FROM (VALUES ('public.idx_pessoas_igreja', 'public.pessoas'), ('public.idx_pessoas_celula', 'public.pessoas'), ('public.idx_pessoas_lider', 'public.pessoas'), ('public.idx_app_users_igreja', 'public.app_users'), ('public.idx_app_users_clerk', 'public.app_users'), ('public.idx_user_roles_igreja', 'public.user_roles'), ('public.idx_role_permissions_igreja', 'public.role_permissions'), ('public.idx_celulas_igreja', 'public.celulas'), ('public.idx_cell_alerts_igreja', 'public.cell_alerts'), ('public.idx_conversations_igreja', 'public.conversations'), ('public.idx_messages_igreja', 'public.messages'), ('public.idx_messages_conversation', 'public.messages'), ('public.idx_work_queue_igreja', 'public.work_queue_items'), ('public.idx_reports_igreja', 'public.reports'), ('public.idx_reports_celula', 'public.reports'), ('public.idx_broadcasts_igreja', 'public.broadcasts'), ('public.idx_events_igreja', 'public.events'), ('public.idx_crons_igreja', 'public.crons'), ('public.idx_system_managers_igreja', 'public.system_managers'), ('public.idx_consolidacoes_igreja', 'public.consolidacoes'), ('public.idx_consol_etapas_igreja', 'public.consolidacao_etapas'), ('public.idx_decisions_igreja', 'public.decisions'), ('public.idx_multiplicacoes_igreja', 'public.multiplicacoes'), ('public.idx_consent_records_igreja', 'public.consent_records'), ('public.idx_ai_usage_logs_igreja', 'public.ai_usage_logs'), ('public.idx_agent_conv_logs_igreja', 'public.agent_conversation_logs')) AS e(idx, tbl) LEFT JOIN pg_index AS i ON i.indexrelid = to_regclass(e.idx)::oid) AS x
  UNION ALL
  SELECT '0003_rls_policies.sql'::text AS migration, 'c01_fn_current_igreja_id'::text AS check_id, 'function'::text AS kind, x.ok, ('current_igreja_id() SECURITY DEFINER returning uuid, reads the JWT sub claim (partial: 20260624_003030/090102 re-create the function) | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
    FROM (SELECT coalesce(pr.oid IS NOT NULL AND pr.prosecdef AND pr.prorettype = to_regtype('uuid')::oid AND strpos(regexp_replace(replace(replace(lower(pg_get_functiondef(pr.oid)), 'public.', ''), 'pg_catalog.', ''), '[[:space:]]+', '', 'g'), 'current_setting(''request.jwt.claim.sub'',true)') > 0, false) AS ok, CASE WHEN pr.oid IS NULL THEN 'absent' ELSE format('secdef=%s config=%s', pr.prosecdef, pr.proconfig) END AS obs FROM (SELECT 1) AS d LEFT JOIN pg_proc AS pr ON pr.oid = to_regprocedure('public.current_igreja_id()')::oid) AS x
  UNION ALL
  SELECT '0003_rls_policies.sql'::text AS migration, 'c02_tenant_policies'::text AS check_id, 'policy'::text AS kind, x.ok, ('tenant_isolation FOR ALL USING/WITH CHECK igreja_id = current_igreja_id() on the 25 tables | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
    FROM (SELECT count(*) FILTER (WHERE p.policyname IS NOT NULL AND p.cmd = 'ALL' AND p.permissive = 'PERMISSIVE' AND strpos(regexp_replace(replace(replace(lower(p.qual), 'public.', ''), 'pg_catalog.', ''), '[[:space:]]+', '', 'g'), 'igreja_id=') > 0 AND strpos(regexp_replace(replace(replace(lower(p.qual), 'public.', ''), 'pg_catalog.', ''), '[[:space:]]+', '', 'g'), 'current_igreja_id()') > 0 AND strpos(regexp_replace(replace(replace(lower(p.with_check), 'public.', ''), 'pg_catalog.', ''), '[[:space:]]+', '', 'g'), 'igreja_id=') > 0 AND strpos(regexp_replace(replace(replace(lower(p.with_check), 'public.', ''), 'pg_catalog.', ''), '[[:space:]]+', '', 'g'), 'current_igreja_id()') > 0) = 25 AS ok, format('%s/%s tables with tenant_isolation (igreja_id = current_igreja_id()); failing: %s', count(*) FILTER (WHERE p.policyname IS NOT NULL AND p.cmd = 'ALL' AND p.permissive = 'PERMISSIVE' AND strpos(regexp_replace(replace(replace(lower(p.qual), 'public.', ''), 'pg_catalog.', ''), '[[:space:]]+', '', 'g'), 'igreja_id=') > 0 AND strpos(regexp_replace(replace(replace(lower(p.qual), 'public.', ''), 'pg_catalog.', ''), '[[:space:]]+', '', 'g'), 'current_igreja_id()') > 0 AND strpos(regexp_replace(replace(replace(lower(p.with_check), 'public.', ''), 'pg_catalog.', ''), '[[:space:]]+', '', 'g'), 'igreja_id=') > 0 AND strpos(regexp_replace(replace(replace(lower(p.with_check), 'public.', ''), 'pg_catalog.', ''), '[[:space:]]+', '', 'g'), 'current_igreja_id()') > 0), 25, coalesce(string_agg(t.name, ',') FILTER (WHERE NOT coalesce(p.policyname IS NOT NULL AND p.cmd = 'ALL' AND p.permissive = 'PERMISSIVE' AND strpos(regexp_replace(replace(replace(lower(p.qual), 'public.', ''), 'pg_catalog.', ''), '[[:space:]]+', '', 'g'), 'igreja_id=') > 0 AND strpos(regexp_replace(replace(replace(lower(p.qual), 'public.', ''), 'pg_catalog.', ''), '[[:space:]]+', '', 'g'), 'current_igreja_id()') > 0 AND strpos(regexp_replace(replace(replace(lower(p.with_check), 'public.', ''), 'pg_catalog.', ''), '[[:space:]]+', '', 'g'), 'igreja_id=') > 0 AND strpos(regexp_replace(replace(replace(lower(p.with_check), 'public.', ''), 'pg_catalog.', ''), '[[:space:]]+', '', 'g'), 'current_igreja_id()') > 0, false)), 'none')) AS obs FROM unnest(ARRAY['pessoas', 'app_users', 'user_roles', 'role_permissions', 'celulas', 'cell_alerts', 'conversations', 'messages', 'work_queue_items', 'reports', 'broadcasts', 'events', 'whatsapp_connections', 'agent_configs', 'llm_credentials', 'crons', 'subscriptions', 'system_managers', 'consolidacoes', 'consolidacao_etapas', 'decisions', 'multiplicacoes', 'consent_records', 'ai_usage_logs', 'agent_conversation_logs']::text[]) AS t(name) LEFT JOIN pg_policies AS p ON p.schemaname = 'public' AND p.tablename = t.name AND p.policyname = 'tenant_isolation') AS x
  UNION ALL
  SELECT '0003_rls_policies.sql'::text AS migration, 'c03_rls_enabled'::text AS check_id, 'rls'::text AS kind, x.ok, ('RLS enabled on the 25 tenant tables + igrejas | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
    FROM (SELECT count(*) FILTER (WHERE c.oid IS NOT NULL AND c.relrowsecurity) = 26 AS ok, format('%s/%s tables ok; failing: %s', count(*) FILTER (WHERE c.oid IS NOT NULL AND c.relrowsecurity), 26, coalesce(string_agg(replace(t.name, 'public.', ''), ',') FILTER (WHERE NOT coalesce(c.oid IS NOT NULL AND c.relrowsecurity, false)), 'none')) AS obs FROM unnest(ARRAY['public.pessoas', 'public.app_users', 'public.user_roles', 'public.role_permissions', 'public.celulas', 'public.cell_alerts', 'public.conversations', 'public.messages', 'public.work_queue_items', 'public.reports', 'public.broadcasts', 'public.events', 'public.whatsapp_connections', 'public.agent_configs', 'public.llm_credentials', 'public.crons', 'public.subscriptions', 'public.system_managers', 'public.consolidacoes', 'public.consolidacao_etapas', 'public.decisions', 'public.multiplicacoes', 'public.consent_records', 'public.ai_usage_logs', 'public.agent_conversation_logs', 'public.igrejas']::text[]) AS t(name) LEFT JOIN pg_class AS c ON c.oid = to_regclass(t.name)::oid AND c.relkind IN ('r', 'p')) AS x
  UNION ALL
  SELECT '0003_rls_policies.sql'::text AS migration, 'c04_pol_igrejas_select'::text AS check_id, 'policy'::text AS kind, x.ok, ('igrejas_self_select FOR SELECT USING (id = current_igreja_id()) | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
    FROM (SELECT coalesce(p.policyname IS NOT NULL AND p.cmd = 'SELECT' AND strpos(regexp_replace(replace(replace(lower(p.qual), 'public.', ''), 'pg_catalog.', ''), '[[:space:]]+', '', 'g'), '(id=') > 0 AND strpos(regexp_replace(replace(replace(lower(p.qual), 'public.', ''), 'pg_catalog.', ''), '[[:space:]]+', '', 'g'), 'current_igreja_id()') > 0, false) AS ok, CASE WHEN p.policyname IS NULL THEN 'absent' ELSE format('cmd=%s %s roles=%s', p.cmd, p.permissive, p.roles) END AS obs FROM (SELECT 1) AS d LEFT JOIN pg_policies AS p ON p.schemaname = 'public' AND p.tablename = 'igrejas' AND p.policyname = 'igrejas_self_select') AS x
  UNION ALL
  SELECT '0004_triggers.sql'::text AS migration, 'c01_functions'::text AS check_id, 'function'::text AS kind, x.ok, ('the 7 trigger functions of 0004 exist | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
    FROM (SELECT count(*) FILTER (WHERE pr.oid IS NOT NULL) = 7 AS ok, format('%s/%s functions ok; failing: %s', count(*) FILTER (WHERE pr.oid IS NOT NULL), 7, coalesce(string_agg(replace(s.sig, 'public.', ''), ',') FILTER (WHERE NOT coalesce(pr.oid IS NOT NULL, false)), 'none')) AS obs FROM unnest(ARRAY['public.fn_set_updated_at()', 'public.fn_promote_pipeline()', 'public.fn_link_cell_promote()', 'public.fn_report_received_clears_queue()', 'public.fn_decision_opens_consolidation()', 'public.fn_consent_on_inbound()', 'public.fn_subscription_autoupgrade()']::text[]) AS s(sig) LEFT JOIN pg_proc AS pr ON pr.oid = to_regprocedure(s.sig)::oid) AS x
  UNION ALL
  SELECT '0004_triggers.sql'::text AS migration, 'c02_triggers'::text AS check_id, 'trigger'::text AS kind, x.ok, ('the 7 triggers of 0004 exist on the right tables bound to the right functions | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
    FROM (SELECT count(*) FILTER (WHERE tg.oid IS NOT NULL AND tg.tgfoid = to_regprocedure(e.fn)::oid) = 7 AS ok, format('%s/%s triggers ok; failing: %s', count(*) FILTER (WHERE tg.oid IS NOT NULL AND tg.tgfoid = to_regprocedure(e.fn)::oid), 7, coalesce(string_agg(e.n, ',') FILTER (WHERE NOT coalesce(tg.oid IS NOT NULL AND tg.tgfoid = to_regprocedure(e.fn)::oid, false)), 'none')) AS obs FROM (VALUES ('public.conversations', 'trg_set_updated_at', 'public.fn_set_updated_at()'), ('public.pessoas', 'trg_promote_pipeline', 'public.fn_promote_pipeline()'), ('public.pessoas', 'trg_link_cell_promote', 'public.fn_link_cell_promote()'), ('public.reports', 'trg_report_received_clears_queue', 'public.fn_report_received_clears_queue()'), ('public.decisions', 'trg_decision_opens_consolidation', 'public.fn_decision_opens_consolidation()'), ('public.messages', 'trg_consent_on_inbound', 'public.fn_consent_on_inbound()'), ('public.pessoas', 'trg_subscription_autoupgrade', 'public.fn_subscription_autoupgrade()')) AS e(t, n, fn) LEFT JOIN pg_trigger AS tg ON tg.tgrelid = to_regclass(e.t)::oid AND tg.tgname = e.n AND NOT tg.tgisinternal) AS x
  UNION ALL
  SELECT '0005_seed.sql'::text AS migration, 'd01_seed_rows'::text AS check_id, 'data_only'::text AS kind, NULL::boolean AS ok, 'Seed of pilot igreja/subscription/agent_config/pessoas/app_user/roles/permissions; DML only, not object-provable (no row reads by design)'::text AS detail
  UNION ALL
  SELECT '0006_harden_function_search_path.sql'::text AS migration, 'c01_search_path'::text AS check_id, 'function'::text AS kind, x.ok, ('the 7 functions of 0004 have proconfig search_path=public, pg_temp (0004 created them without SET) | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
    FROM (SELECT count(*) FILTER (WHERE pr.oid IS NOT NULL AND pr.proconfig @> ARRAY['search_path=public, pg_temp']::text[]) = 7 AS ok, format('%s/%s functions ok; failing: %s', count(*) FILTER (WHERE pr.oid IS NOT NULL AND pr.proconfig @> ARRAY['search_path=public, pg_temp']::text[]), 7, coalesce(string_agg(replace(s.sig, 'public.', ''), ',') FILTER (WHERE NOT coalesce(pr.oid IS NOT NULL AND pr.proconfig @> ARRAY['search_path=public, pg_temp']::text[], false)), 'none')) AS obs FROM unnest(ARRAY['public.fn_set_updated_at()', 'public.fn_promote_pipeline()', 'public.fn_link_cell_promote()', 'public.fn_report_received_clears_queue()', 'public.fn_decision_opens_consolidation()', 'public.fn_consent_on_inbound()', 'public.fn_subscription_autoupgrade()']::text[]) AS s(sig) LEFT JOIN pg_proc AS pr ON pr.oid = to_regprocedure(s.sig)::oid) AS x
  UNION ALL
  SELECT '0007_remove_demo_data.sql'::text AS migration, 'd01_demo_delete'::text AS check_id, 'data_only'::text AS kind, NULL::boolean AS ok, 'DELETE of demo messages/conversation/pessoas/celula; DML only, not object-provable'::text AS detail
  UNION ALL
  SELECT '0008_add_operador_role.sql'::text AS migration, 'c01_enum_user_role'::text AS check_id, 'enum'::text AS kind, x.ok, ('user_role_papel contains ''operador'' | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
    FROM (SELECT coalesce((SELECT count(DISTINCT e.enumlabel) FROM pg_enum AS e WHERE e.enumtypid = to_regtype('public.user_role_papel')::oid AND e.enumlabel = ANY (ARRAY['operador']::text[])) = 1, false) AS ok, CASE WHEN to_regtype('public.user_role_papel') IS NULL THEN 'type absent' ELSE 'labels: ' || coalesce((SELECT string_agg(e.enumlabel, ',' ORDER BY e.enumsortorder) FROM pg_enum AS e WHERE e.enumtypid = to_regtype('public.user_role_papel')::oid), '') END AS obs) AS x
  UNION ALL
  SELECT '0008_add_operador_role.sql'::text AS migration, 'c02_enum_role_perm'::text AS check_id, 'enum'::text AS kind, x.ok, ('role_perm_papel contains ''operador'' | observed: ' || coalesce(x.obs, 'n/a'))::text AS detail
