_privilege(to_regrole('authenticated')::oid, to_regprocedure('public.purpose_consent_governance_draft_valid(jsonb)')::oid, 'EXECUTE')::text) END AS obs) AS x, (SELECT CASE WHEN to_regclass('public.purpose_consent_governance_envelope')::oid IS NULL THEN false ELSE (SELECT count(*) FROM pg_policy AS p WHERE p.polrelid = to_regclass('public.purpose_consent_governance_envelope')::oid) = 0 END AS ok, CASE WHEN to_regclass('public.purpose_consent_governance_envelope')::oid IS NULL THEN 'table absent' ELSE format('%s policies', (SELECT count(*) FROM pg_policy AS p WHERE p.polrelid = to_regclass('public.purpose_consent_governance_envelope')::oid)) END AS obs) AS y) AS x
